import static org.junit.Assert.assertSame;

public class XYSeries_addOrUpdate_TriageGen0Test {



    @Test
    public void testAddOrUpdate_AllowDuplicatesTrue() {
        // allowDuplicateXValues = true
        XYSeries series = new XYSeries("Test", false, true);

        // When duplicates are allowed, it calls add(x, y) and returns null
        XYDataItem result = series.addOrUpdate(1.0, 10.0);

        assertNull("Should return null when allowDuplicateXValues is true", result);
        assertEquals(1, series.getItemCount());
        assertEquals(1.0, series.getX(0).doubleValue(), 0.001);
        assertEquals(10.0, series.getY(0).doubleValue(), 0.001);
    }










}

