import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class XYSeries_addOrUpdate_TriageGen0Test {







    @Test
    public void testAddOrUpdate_NoDuplicates_AddNew_WithAutoSort() {
        // autoSort = true, allowDuplicateXValues = false
        XYSeries series = new XYSeries("Test", true, false);

        // Add first item
        series.addOrUpdate(2.0, 20.0);
        // Add second item (out of order)
        XYDataItem result = series.addOrUpdate(1.0, 10.0);

        assertNull("Should return null when adding new item", result);
        assertEquals(2, series.getItemCount());
        // Check sorting: 1.0 should be at index 0
        assertEquals(1.0, series.getX(0).doubleValue(), 0.001);
        assertEquals(2.0, series.getX(1).doubleValue(), 0.001);
    }






}

