import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class XYSeries_addOrUpdate_TriageGen0Test {













    @Test
    public void testAddOrUpdate_BinarySearchInsertionIndex() {
        // Testing the "else" block with autoSort and negative index from binarySearch
        XYSeries series = new XYSeries("Test", true, false);

        // Add 10.0
        series.addOrUpdate(10.0, 100.0);
        // Add 20.0
        series.addOrUpdate(20.0, 200.0);

        // Add 15.0 -> binarySearch should return -(insertion point) - 1
        // insertion point is index 1. index = -1 - 1 = -2.
        // -index * 1 = 2. Wait, logic in code: data.add(-index * 1, ...)
        // If index is -2, -(-2)*1 = 2. 
        // Actually, let's look at the math: if index is -2, -index is 2.
        // If we want to insert at index 1, index should be -2.

        series.addOrUpdate(15.0, 150.0);

        assertEquals(3, series.getItemCount());
        assertEquals(10.0, series.getX(0).doubleValue(), 0.001);
        assertEquals(15.0, series.getX(1).doubleValue(), 0.001);
        assertEquals(20.0, series.getX(2).doubleValue(), 0.001);
    }
}
